// ── The world map: data, views and taps ──────────────────────────────────────
//
// Client-safe (no country table). The shapes come from public/geo/world-50m.json,
// GENERATED by supabase/geography/build-map.mts from Natural Earth 1:50m
// (public domain). They are fetched once and cached, never bundled.
//
// Coordinates: the file stores longitude/latitude in hundredths of a degree.
// A view picks a centre meridian lon0 and projects with the Natural Earth
// projection (lib/geo-projection.ts) into SVG units: SCALE per radian, y down.
// A tap is turned back into latitude/longitude with the exact inverse.
//
// No '@/' imports, so the Node checks can load this file.

import { project, invert, wrapLon, haversineKm } from './geo-projection'
import type { Continent } from './geo-data'

export { haversineKm }

export const MAP_URL = '/geo/world-50m.json'
/** SVG units per projected radian. */
export const SCALE = 1000

export interface AssetEntry {
  /** ISO alpha-3 (Natural Earth ADM0_A3 for non-members, e.g. KOS). */
  a: string
  /** ISO alpha-2 of a UN member. Absent = neutral land, never asked. */
  i?: string
  /** The asked capital, [lon, lat]. */
  k?: [number, number]
  /** Zoom box for "Name that country", [w, s, e, n] (w/e may pass ±180). */
  z?: [number, number, number, number]
  /** Land area, km². */
  ar?: number
  /** Rings: [lon0, lat0, dlon1, dlat1, ...] in 1/q degrees. */
  r: number[][]
}
export interface MapAsset { v: number; src: string; sha256: string; q: number; c: AssetEntry[] }

/** Longitude/latitude box; w and e may run past ±180 (e > w always). */
export interface Box { w: number; s: number; e: number; n: number }

export interface MapShape {
  a3:    string
  iso?:  string
  cap?:  { lon: number; lat: number }
  zoom?: Box
  km2:   number
  /** Each ring as [lon, lat, lon, lat, ...] in degrees. */
  rings: Float64Array[]
  /** Centre longitude of each ring, to decide which side of a seam it goes. */
  mids:  number[]
}

export function decodeAsset(a: MapAsset): MapShape[] {
  return a.c.map(e => {
    const rings = e.r.map(r => {
      const out = new Float64Array(r.length)
      let x = 0, y = 0
      for (let i = 0; i < r.length; i += 2) {
        x += r[i]; y += r[i + 1]
        out[i] = x / a.q; out[i + 1] = y / a.q
      }
      return out
    })
    const mids = rings.map(r => {
      let lo = Infinity, hi = -Infinity
      for (let i = 0; i < r.length; i += 2) { if (r[i] < lo) lo = r[i]; if (r[i] > hi) hi = r[i] }
      return (lo + hi) / 2
    })
    return {
      a3: e.a, iso: e.i, km2: e.ar ?? 0, rings, mids,
      cap: e.k ? { lon: e.k[0], lat: e.k[1] } : undefined,
      zoom: e.z ? { w: e.z[0], s: e.z[1], e: e.z[2], n: e.z[3] } : undefined,
    }
  })
}

let cache: Promise<MapShape[]> | null = null
/** The shapes, fetched once per page load. */
export function loadMap(): Promise<MapShape[]> {
  if (!cache) {
    cache = fetch(MAP_URL)
      .then(r => { if (!r.ok) throw new Error(`map ${r.status}`); return r.json() as Promise<MapAsset> })
      .then(decodeAsset)
      .catch(e => { cache = null; throw e })
  }
  return cache
}

// ── Regions ──────────────────────────────────────────────────────────────────
//
// What a continent view shows. Chosen so every capital of the continent is
// inside, and as little else as possible, so phones get the most pixels per
// kilometre. Oceania runs past 180° so Samoa and Tonga sit beside Fiji.

export type Region = Continent | 'world'
export const REGION_BOX: Record<Region, Box> = {
  world: { w: -180, s: -57, e: 180, n: 83 },
  af:    { w: -26,  s: -36, e: 60,  n: 38 },
  as:    { w: 25,   s: -12, e: 150, n: 56 },
  eu:    { w: -25,  s: 34,  e: 45,  n: 71.5 },
  na:    { w: -130, s: 5,   e: -55, n: 60 },
  sa:    { w: -82,  s: -56, e: -34, n: 13 },
  oc:    { w: 110,  s: -48, e: 192, n: 10 },
}

// ── Views ────────────────────────────────────────────────────────────────────

/** A rectangle in SVG units, plus the meridian it is centred on. */
export interface View { lon0: number; x: number; y: number; w: number; h: number }

/** Degrees to SVG units for a view centred on lon0. `near` keeps the point
 *  on the same side of the map's seam as the view centre. */
export function toSvg(lon: number, lat: number, lon0: number): [number, number] {
  const [x, y] = project(lon, lat, lon0)
  return [x * SCALE, -y * SCALE]
}

/** SVG units back to degrees, or null off the edge of the world. */
export function fromSvg(x: number, y: number, lon0: number): { lat: number; lon: number } | null {
  return invert(x / SCALE, -y / SCALE, lon0)
}

/** The view that shows `box`, widened to the container's shape (w / h). */
export function fitView(box: Box, aspect: number, pad = 0.04): View {
  const lon0 = wrapLon((box.w + box.e) / 2)
  const half = (box.e - box.w) / 2
  let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity
  // The outline of a lon/lat box is curved in this projection: sample it.
  for (let i = 0; i <= 16; i++) {
    const t = i / 16
    const pts: [number, number][] = [
      [-half + 2 * half * t, box.s], [-half + 2 * half * t, box.n],
      [-half, box.s + (box.n - box.s) * t], [half, box.s + (box.n - box.s) * t],
    ]
    for (const [dl, lat] of pts) {
      const [x, y] = project(dl, lat, 0, true)
      x0 = Math.min(x0, x * SCALE); x1 = Math.max(x1, x * SCALE)
      y0 = Math.min(y0, -y * SCALE); y1 = Math.max(y1, -y * SCALE)
    }
  }
  let w = (x1 - x0) * (1 + 2 * pad), h = (y1 - y0) * (1 + 2 * pad)
  const cx = (x0 + x1) / 2, cy = (y0 + y1) / 2
  if (w / h < aspect) w = h * aspect
  else h = w / aspect
  return { lon0, x: cx - w / 2, y: cy - h / 2, w, h }
}

export interface ProjectedShape {
  a3: string
  iso?: string
  /** SVG path data for every ring, in the view's projection. */
  d: string
  /** Bounding box in SVG units. */
  x0: number; y0: number; x1: number; y1: number
}

/** Every shape projected for a view centred on lon0. Each ring is moved by
 *  whole turns so it sits nearest lon0 and is drawn in one piece. */
export function projectShapes(shapes: MapShape[], lon0: number): ProjectedShape[] {
  return shapes.map(s => {
    let d = ''
    let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity
    s.rings.forEach((r, ri) => {
      const rel = wrapLon(s.mids[ri] - lon0)
      const shift = rel - (s.mids[ri] - lon0)          // whole turns
      for (let i = 0; i < r.length; i += 2) {
        const [px, py] = project(r[i] + shift, r[i + 1], lon0, true)
        const x = Math.round(px * SCALE * 10) / 10, y = Math.round(-py * SCALE * 10) / 10
        d += (i === 0 ? 'M' : 'L') + x + ' ' + y
        if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y
      }
      d += 'Z'
    })
    return { a3: s.a3, iso: s.iso, d, x0, y0, x1, y1 }
  })
}

/** Points along the great circle from a to b, for drawing a pin's line. */
export function greatCircle(a: { lat: number; lon: number }, b: { lat: number; lon: number }, n = 32): { lat: number; lon: number }[] {
  const D2R = Math.PI / 180
  const v = (p: { lat: number; lon: number }) => [
    Math.cos(p.lat * D2R) * Math.cos(p.lon * D2R), Math.cos(p.lat * D2R) * Math.sin(p.lon * D2R), Math.sin(p.lat * D2R)]
  const [p, q] = [v(a), v(b)]
  const dot = Math.max(-1, Math.min(1, p[0] * q[0] + p[1] * q[1] + p[2] * q[2]))
  const om = Math.acos(dot)
  if (om < 1e-9) return [a, b]
  const out: { lat: number; lon: number }[] = []
  for (let i = 0; i <= n; i++) {
    const t = i / n
    const k1 = Math.sin((1 - t) * om) / Math.sin(om), k2 = Math.sin(t * om) / Math.sin(om)
    const x = k1 * p[0] + k2 * q[0], y = k1 * p[1] + k2 * q[1], z = k1 * p[2] + k2 * q[2]
    out.push({ lat: Math.atan2(z, Math.hypot(x, y)) / D2R, lon: Math.atan2(y, x) / D2R })
  }
  return out
}

/** Screen pixels a country's land would cover per side, roughly: under
 *  TINY_PX it is drawn as a ring around its capital instead. */
export const TINY_PX = 9
export function sidePx(km2: number, pxPerUnit: number): number {
  // One SVG unit is 1/SCALE radian, about 6371/SCALE km on the ground.
  return Math.sqrt(km2) / (6371 / SCALE) * pxPerUnit
}
